import hashlib
import hmac
import os
import unicodedata
from functools import wraps
from flask import Flask, request, jsonify, abort, session
import secrets
import re

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET_KEY', secrets.token_hex(32))

# Secure token verification with HMAC
API_SECRET = os.environ.get('API_SECRET', secrets.token_hex(32)).encode()

def verify_api_token(token):
    """Verify API token using HMAC - constant time comparison"""
    if not token or len(token) < 10:
        return False
    parts = token.split(':')
    if len(parts) != 2:
        return False
    user_id, provided_mac = parts
    expected_mac = hmac.new(API_SECRET, user_id.encode('utf-8'), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected_mac, provided_mac)

# Role-based access control
USER_ROLES = {
    'admin': {'read', 'write', 'delete', 'admin'},
    'editor': {'read', 'write'},
    'viewer': {'read'}
}

# Protected resource paths and required permissions
RESOURCE_PERMISSIONS = {
    '/api/documents': 'read',
    '/api/documents/create': 'write',
    '/api/documents/delete': 'delete',
    '/api/admin/users': 'admin',
    '/api/admin/config': 'admin',
    '/api/admin/secrets': 'admin',
}

def get_user_role(user_id):
    """Lookup user role from database (simplified)"""
    # In production this queries a database
    role_map = {'user1': 'admin', 'user2': 'editor', 'user3': 'viewer'}
    return role_map.get(user_id, 'viewer')

def normalize_request_path(path):
    """Normalize the request path for consistent matching.
    Handles URL-encoded characters and Unicode normalization
    to prevent bypass via encoding tricks."""
    # Decode percent-encoded characters
    from urllib.parse import unquote
    decoded_path = unquote(path)
    # Apply Unicode NFKC normalization for consistent comparison
    normalized = unicodedata.normalize('NFKC', decoded_path)
    # Remove trailing slashes for consistency
    normalized = normalized.rstrip('/')
    # Collapse multiple slashes
    normalized = re.sub(r'/+', '/', normalized)
    # Reject any path containing non-ASCII after normalization
    if not all(ord(c) < 128 for c in normalized):
        return None
    return normalized

def check_path_permission(normalized_path, user_permissions):
    """Check if user has permission for the requested path.
    Uses prefix matching to handle sub-resources."""
    if normalized_path is None:
        return False, 'invalid_path'
    for protected_path, required_perm in RESOURCE_PERMISSIONS.items():
        # Check if the normalized request path starts with a protected path
        if normalized_path.startswith(protected_path):
            if required_perm not in user_permissions:
                return False, required_perm
    return True, None

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-API-Token', '')
        if not verify_api_token(token):
            abort(401)
        user_id = token.split(':')[0]
        role = get_user_role(user_id)
        permissions = USER_ROLES.get(role, set())

        # Normalize and check path permissions
        norm_path = normalize_request_path(request.path)
        allowed, needed = check_path_permission(norm_path, permissions)
        if not allowed:
            abort(403)

        request.user_id = user_id
        request.user_role = role
        return f(*args, **kwargs)
    return decorated

@app.route('/api/documents', methods=['GET'])
@require_auth
def list_documents():
    return jsonify({'documents': ['doc1', 'doc2', 'doc3']})

@app.route('/api/documents/create', methods=['POST'])
@require_auth
def create_document():
    data = request.get_json()
    if not data or 'title' not in data:
        abort(400)
    return jsonify({'status': 'created', 'title': data['title']})

@app.route('/api/admin/secrets', methods=['GET'])
@require_auth
def get_secrets():
